const active=new Set();document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{const tag=button.dataset.filter;active.has(tag)?active.delete(tag):active.add(tag);button.setAttribute('aria-pressed',String(active.has(tag)));document.querySelectorAll('[data-tags]').forEach(item=>item.hidden=active.size>0&&![...active].some(t=>item.dataset.tags.split(' ').includes(t)));document.querySelectorAll('.menu-group').forEach(section=>section.hidden=![...section.querySelectorAll('[data-tags]')].some(i=>!i.hidden))}));
